import XCTest

class SimpleUITest: XCTestCase {
    func testTapOpenButton() {
        let app = XCUIApplication()
        app.activate()

        // Look for the Open button and tap it
        let openButton = app.buttons["Open"]
        if openButton.exists && openButton.isHittable {
            openButton.tap()
            sleep(1)
        }
    }
}
EOF

# Try to run the test
