import XCTest

extension XCUIApplication {
    func tapButton(withLabel label: String) {
        let button = buttons[label]
        guard button.exists else { return }
        button.tap()
    }
}

// Try to interact with the dialog
let app = XCUIApplication()
app.activate()
sleep(1)

// Try to tap the Open button
let openButton = app.buttons["Open"]
if openButton.exists {
    openButton.tap()
    print("Tapped Open button")
} else {
    print("Open button not found")
}
EOF

